import pandas as pd

def count_employees(employees: pd.DataFrame) -> pd.DataFrame:
    merged = employees.merge(employees, left_on='employee_id', right_on='reports_to', suffixes=('_mgr', '_emp'))
    res = merged.groupby(['employee_id_mgr', 'name_mgr']).agg(
        reports_count=('employee_id_emp', 'count'),
        average_age=('age_emp', lambda x: int(round(x.mean() + 1e-9)))
    ).reset_index()
    res.rename(columns={'employee_id_mgr': 'employee_id', 'name_mgr': 'name'}, inplace=True)
    return res.sort_values(by='employee_id')
